insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('67ac33f1-b8f1-4f3e-a7e5-29a94022c691','zh','shitou-jianzi-bu-opera-rita','石头剪刀布(歌剧《丽塔》)梗','2015年歌剧《丽塔》中"石头剪刀布专业户"台词,2024年被重新发掘后走红','演员崔宰林、李经受主演的2015年歌剧《丽塔》中有一幕,两名男子在进行石头剪刀布对决前,各自唱出自己的"专业"是什么,这一片段在2024年夏天被短视频重新发掘后爆红。常被改编成"我大学时代主修过○○"的句式,填入各种内容使用。','2015年歌剧《丽塔》演出影像于2024年7月前后被YouTube Shorts重新关注','用于郑重其事又滑稽地宣称自己擅长某事时的改编句式',null,array['묵찌빠(오페라 리타) 밈', '난 대학 시절 묵찌빠를 전공했단 사실', '石头剪刀布学系'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('880c7149-2d93-407f-aa19-582e4fe309d4','zh','hot-candy','H.O.T.《Candy》','1996年H.O.T.现象级热曲《Candy》及其编舞','1996年发行的H.O.T.《Candy》是偶像组合史上首支现象级大热曲,受到全年龄层喜爱。姜熙俊的打针舞、张友赫的锤子舞、文熙俊的能量战士舞等成员各自的标志性编舞相继诞生,使这首歌成为象征第一代偶像粉丝文化的代表作。','1996年作为H.O.T.首张专辑后续曲目发行。SM原本主推《Candy》为主打曲,但依成员意见先发行了《战士的后裔》。该曲因抄袭争议中止活动后,《Candy》作为后续曲开始活动,据传作曲人张龙镇当时是与H.O.T.成员同龄的高中生。文熙俊的能量战士舞、张友赫的锤子舞等成员各自的编舞,连同毛线帽、毛绒服饰的搭配一同在青少年间流行开来,使该曲成为偶像史上首支现象级热曲,也带动了一场街头时尚风潮。','可作为第一代偶像编舞文化的代表案例引用',null,array['H.O.T. 캔디', '캔디춤', '주사춤', '打针舞'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('3ee79725-7120-4170-b3a5-8a0cc9bf164c','zh','xiexie-sato','谢谢你,佐藤(G.G.佐藤)','2008年北京奥运会韩日大战中因失误而闻名的日本外野手佐藤的"感谢"梗','在2008年北京奥运会棒球半决赛的韩日对决中,日本代表队选手G.G.佐藤在防守时漏接了高英民打出的高飞球,该失误助韩国队取胜。解说员许球连在转播中说出"谢谢你,佐藤"一语成为契机,此后每当国际比赛中对方选手的重大失误使韩国受益时,人们便会用"谢谢你,○○"来调侃,逐渐固定为一种梗。即便过去十多年,这一幕仍被称为"世纪落球"而被反复提起。','2008年北京奥运会韩日之战的失误画面及解说员许球连的发言','国际比赛中因对方失误使韩国获利时,用来表达(反讽式)感谢的梗',null,array['고마워요 사토 (G.G.사토)', 'G.G.사토', '世纪落球'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('48653a33-c3d5-4ee4-9670-330c1a145118','zh','ppap-pen-pineapple-apple-pen','PPAP(笔-菠萝-苹果-笔)','日本喜剧演员Piko太郎创作的洗脑神曲,在全球及韩国爆红的全球性梗','2016年8月25日,Piko太郎(古坂大魔王)在YouTube上传的一段短视频,凭借简单重复的歌词与舞蹈像"耳虫"一样迅速传播,连CNN都称其为"新江南Style",风靡全球。韩国于2016年10月正式发行该曲,SNL Korea的权赫秀、TWICE的周子瑜与彩瑛等纷纷模仿翻跳,人气高涨。','2016年8月日本Piko太郎在YouTube公开,随后风靡全球','常被用作短小无厘头的模仿创作素材',null,array['PPAP (펜-파인애플-애플-펜)', '펜파인애플애플펜', '笔菠萝苹果笔', 'Piko太郎'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('43b7c300-94ef-46b0-8064-5b1dbefb0697','zh','gfriend-rough-dance-challenge','GFRIEND《奔跑吧,时间》编舞挑战','GFRIEND《奔跑吧,时间》高难度旋转动作编舞引发的翻跳热潮','2016年1月发行的GFRIEND《奔跑吧,时间(Rough)》,以成员们在舞台上多次跌倒却仍坚持跳完全曲的高强度编舞引发热议,这种"拼尽全力"的形象与"神一样的女友(갓자친구)"称号一同获得广泛好评。翻跳视频数量激增,截至2019年相关视频已达约4万个。','2016年1月GFRIEND发行《奔跑吧,时间(Rough)》,高强度编舞引发热议','常被引用为展现拼尽全力的编舞案例',null,array['여자친구 ''시간을 달려서'' 안무 챌린지', '여자친구 시간을달려서 커버댄스', '旋转编舞'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;



