insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('56eaf9a9-f4c2-42ad-94e5-2552246b843c','zh','twice-tt-pose-challenge','TWICE《TT》表情手势挑战','TWICE《TT》标志性表情包式表情与手指造型带来的编舞挑战','2016年10月发行的TWICE《TT》,以模拟字母"TT"(哭脸表情符号)造型的手指姿势与表情动作为特色,发行后翻跳与模仿这一手势的挑战迅速爆红。在2016年MAMA舞台上与《CHEER UP》一同呈现的组合舞台,被誉为当年最具代表性的K-POP表演之一。','2016年10月TWICE《TT》发行,编舞亮点走红','常用于可爱编舞亮点的模仿翻跳内容',null,array['TT 표정·손가락 챌린지 (트와이스)', '트와이스 TT 표정', 'TT手势'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('cd878fab-b5a2-439d-b375-ab55a530150b','zh','rain-bad-guy','Rain《坏男人》','歌手兼演员Rain(郑智薰)2002年solo出道主打曲','2002年5月发行的Rain solo出道专辑主打曲,由朴振英参与作词作曲。此后凭借后续曲《不说再见》获得更大人气,Rain由此成长为2000年代最具代表性的男性solo歌手。','2002年5月13日作为Rain首张专辑主打曲发行','常在谈论Rain出道初期经历时被提及',null,array['비 - 나쁜 남자', 'Rain 데뷔곡', 'Rain出道曲'],'[{"text": "听过Rain出道初期的《坏男人》吗?", "situation": "聊天"}, {"text": "这首歌就是Rain的起点啊", "situation": "社交媒体评论"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('3d6d5fb3-22f6-44d8-bcf4-7cba42362065','zh','into-the-arena','Into the Arena','申海澈为2002年世界杯创作的应援曲,收录于官方应援专辑','歌手申海澈为2002年韩日世界杯特别制作的应援曲,收录于世界杯官方应援专辑《梦想成真》的第1首。该曲被认为为"大~韩民国"拍手节奏的广泛传播做出了贡献。','申海澈在2002年世界杯期间创作,收录于官方应援专辑','常被提及为2002年世界杯应援文化的背景音乐',null,array['Into the Arena', '신해철 월드컵 응원가', '梦想成真收录曲'],'[{"text": "这次应援放申海澈的Into the Arena吧", "situation": "聊天"}, {"text": "说到2002年应援曲怎么能少了这首", "situation": "社交媒体评论"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('d661eec7-a57d-476d-b066-af32ff114b60','zh','who-coughed','是谁咳嗽了','电视剧《太祖王建》中弓裔用观心法时因臣子咳嗽而问责的场景,后来被重新发掘成梗','2000年KBS大河剧《太祖王建》第80集中,弓裔在施展"观心法"时因臣子的咳嗽声而勃然大怒的场景。播出当时并未引起太大反响,直到2015年前后被网络社区重新发掘,此后常被改编——将"咳嗽"替换成其他词语进行调侃,成为广为流传的经典梗。','2000年KBS《太祖王建》第80集弓裔场景,2015年前后重新走红','用于讽刺对荒诞或琐碎小事反应过度的情况',null,array['누가 기침 소리를 내었는가', '궁예 관심법 짤', '咳嗽声梗'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('c2a24029-dd2d-46f8-a36b-f0e0f4e7236b','zh','korean-girl-perfect-circle','韩国女高中生的"神级画圆"','韩国女高中生用手臂当圆规画出完美圆形的7秒视频,2021年风靡全球','该视频发布于2021年5月3日,画面中一名女高中生像圆规一样挥动手臂,在黑板上画出一个近乎完美的圆形,随后说了一句"啊,怎么这么没劲啊"。高完成度的圆形、优雅的动作与云淡风轻的反应相结合,使这段视频不仅在韩国国内走红,也在海外网民中广为流传,成为知名梗。','韩国某女高中生的黑板画圆视频(发布于2021年5月3日)','适合用来形容看似没什么大不了、却出人意料地很擅长的技能',null,array['흔한 여고생들의 뻘짓', '칠판 원그리기', '黑板画圆'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;



