insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('8bbdf79d-aa64-4f10-8d51-88ac4a645a9e','zh','lee-jung-hyun-wa-bakkwo','李贞贤《Wa》《换(바꿔)》','1999年李贞贤颠覆性的科技舞曲(Techno)造型','1999年10月发行的李贞贤单曲《Wa》引领了当年下半年的科技舞曲(Techno)热潮,人气持续近四个月之久。画有独眼图案的红色扇子、佩戴在小指上的麦克风,以及神似巫堂服饰的造型,共同营造出世纪末氛围的颠覆性概念,引发热议;后续曲《换(바꿔)》中的机械翅膀造型同样话题十足。','源自1999年10月20日发行的李贞贤首张专辑《Let''s Go To My Star》主打曲《Wa》的造型概念。红色独眼扇、手指麦克风、长发簪与带有萨满色彩的服饰等颠覆性造型,据说在所属公司内部也曾引发强烈反对,是超前于时代的尝试。这一造型概念将1999年下半年席卷歌坛的科技舞曲热潮推向大众化风潮,李贞贤也因此获得"科技女战士"的绰号。','可作为1999年世纪末科技舞曲造型的代表案例引用',null,array['이정현 ''바꿔''·''와''', '바꿔', '와', '独眼扇'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('de173441-cc53-46db-adbc-aa003f846e3e','zh','naruto-run','火影跑','模仿《火影忍者》上身前倾、双臂后甩的招牌奔跑姿势的梗','《火影忍者》系列中忍者们独特的奔跑姿势——上身向前倾、双臂向后甩——在现实中被真人模仿拍摄的视频曾风靡全球。在韩国,这一姿势甚至被用于火影游戏的官方广告中,足见其知名度;在公共场所以这一姿势奔跑的真人挑战视频也持续被分享传播。','动画《火影忍者》(2002年播出)中忍者的奔跑姿势','广泛用于真人模仿、角色扮演类视频',null,array['나루토 런', '나루토 달리기', 'Naruto Run'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('c0a77629-01fb-437d-b2a2-4be1be7bdf07','zh','dubai-chewy-cookie','"迪拜黏韧曲奇"热潮(두쫀쿠)','2026年初"迪拜黏韧曲奇"引发开店排队抢购的甜品热潮','以棉花糖面团包裹卡达伊夫酥丝与开心果奶油制成的"迪拜黏韧曲奇",简称"두쫀쿠",自2025年末开始口碑扩散,到2026年初在韩国全国引发排队抢购与迅速售罄的热潮。社交媒体打卡消费与从众效应叠加,使其传播速度极快,自制DIY视频也随之流行,并被介绍到海外引发关注。','源自2022年流行的"迪拜巧克力",2026年初在韩国国内引发爆发式流行','常用作甜品测评、吃播内容素材',null,array['두쫀쿠 신드롬', '두바이 쫀득 쿠키', '두쫀쿠'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('889daeb1-58c5-4476-91a1-84f5b73a8707','zh','shinkansen-derail-shot','新干线大脱轨射门','韩国网民为嘲讽日本前锋浪费绝佳得分机会而起的射门梗名','日本前锋柳泽敦在球门前面对绝佳得分机会时严重踢飞,韩国网民将这一幕比作"疾驰的新干线脱轨",戏称为"新干线大脱轨射门"。这场比赛中,日本原本领先澳大利亚,却在下半场连丢三球遭逆转落败。此后,该说法被广泛用来嘲讽白白错失绝佳得分机会的情况。','韩国网民为日本国家足球队比赛中决定性的射门失误画面命名','用于调侃错失绝佳机会的足球运动员',null,array['신칸센 대탈선슛'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('7ba7be7c-0a33-4e4c-8bc8-5969101c75df','zh','girls-generation-forever-1-15th','少女时代出道15周年《FOREVER 1》','少女时代出道15周年全员回归专辑与主打曲','少女时代为纪念出道15周年,于2022年8月发行全员回归专辑《FOREVER 1》。主打曲再度由创作少女时代出道曲的Kenzie参与制作,专辑在全球31个地区iTunes专辑榜登顶,引发热烈反响,9月还举办了大型粉丝活动。','少女时代出道15周年纪念全员回归专辑《FOREVER 1》(2022年8月发行)','常用于谈论老牌粉丝群体的全员回归重聚话题',null,array['소녀시대 Forever 1 15주년', '포에버원', 'Forever 1'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;



