insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('44051e47-450c-4704-8fe5-49d69ba1a215','zh','baofeng-yichong','暴风异虫','洪进浩凌厉进攻的异虫打法而得的绰号','2001年可口可乐杯On Game Net星际联赛等赛事中,洪进浩与林遥焕在决赛展开激烈较量,由此崭露头角并获得"暴风异虫"的绰号,形容其如暴风骤雨般凶猛的进攻物量打法。此后他也因屡屡屈居亚军而被称为"孔亚军(콩라인)",这一形象与"暴风异虫"绰号一同成为洪进浩的标志性称号。','2001年On Game Net星际联赛,洪进浩绰号首次流传开来','常用于形容星际争霸初创时期活跃出彩的选手',null,array['폭풍저그', '洪进浩暴风异虫'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('63fd8794-1005-422c-901b-16ed99f25efa','zh','lin-jiang-vs-zhan-jiang','淋酱吃 vs 蘸酱吃(糖醋肉酱汁之争)','围绕糖醋肉酱汁该淋着吃还是蘸着吃展开的无解之争','2013年综艺《无限挑战》中,郑俊夏将酱汁直接淋在糖醋肉上,柳在锡对此表示反对的画面成为话题,随后经过2014年游戏社区的模仿传播,到2018年前后固定为大众化的梗。它常被用作代表"争不出结果的无意义争论",也频繁出现在对艺人、政治人物的提问中,并在各类模仿与综艺内容中反复被消费。','2013年综艺《无限挑战》相关场面引发话题,2018年前后大众化','常用作轻松的口味喜好类争论话题',null,array['부먹 vs 찍먹', '부먹찍먹 논쟁'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('d51b8be9-be9a-4c75-bed9-955ff8f5caf4','zh','nani-ga-suki-challenge','"喜欢什么"告白挑战(나니가스키)','用《Love Live》组合歌曲歌词改编的"最爱告白"挑战','动画《Love Live》组合AiScReam的歌曲《爱♡冰淇淋!(아이♡스크림!)》中"나니가 스키?(喜欢什么?)"一句歌词为基础,让参与者说出自己喜欢的对象的挑战。2025年3月登顶日本TikTok与韩国Spotify病毒榜单第一名,IVE、NMIXX、Kep1er、BOYNEXTDOOR等偶像团体也纷纷参与。','2025年3月源自日本动画《Love Live》组合歌曲,随后扩散至整个亚洲','适用于表白最爱、示爱类内容',null,array['나니가스키 챌린지', '何がスキ', '冰淇淋挑战'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('5a70b638-0aa4-4135-a57f-c57918a535cf','zh','bbikki-bbikki-challenge','哔叽哔叽舞蹈挑战','源自起亚啦啦队视频、席卷全球的手势舞挑战','起亚老虎队啦啦队员李珠恩的短视频引发热议,由此掀起的舞蹈潮流,其标志性动作是竖起拇指、手臂呈"ㄴ"字形上下摆动。背景音乐使用了印尼DJ对H.O.T.出身张友赫、Tony An、李在元组成的JTL组合歌曲《My Lecon》改编的混音曲《Out Song》。2024年下半年席卷韩国内外社交媒体。','2024年6月YouTube频道"내맘찍영"上传的起亚啦啦队员李珠恩短视频','适合在热闹氛围中跟跳',null,array['삐끼삐끼 챌린지', '삐끼삐끼춤', 'Out Song挑战'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('80517a0d-8172-4349-b802-fa80a0f39382','zh','twice-look-at-me-challenge','TWICE《Look at Me(날 바라바라봐)》挑战','2017年TWICE收录曲经海外粉丝挑战带动、2024年爆冷翻红的案例','《Look at Me(날 바라바라봐)》是TWICE 2017年首张正规专辑的收录曲,当时并未受到太多关注。但2024年海外粉丝制作的简单编舞《Look at Me》挑战在TikTok上扩散开来,TWICE成员们亲自参与挑战后人气进一步加速。最终该曲在TikTok发布的《2024年度盘点(Year on TikTok 2024)》中登顶韩国最热歌曲榜首。','2017年作为TWICE首张正规专辑收录曲发行,2024年因海外粉丝制作的《Look at Me》挑战而爆冷翻红,登顶TikTok《Year on TikTok 2024》韩国最热歌曲榜首','常用于简单编舞挑战视频或"爆冷翻红歌曲"相关介绍内容',null,array['트와이스 날 바라바라봐 챌린지', 'Look at Me 챌린지', 'Look at Me舞蹈'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;



